-- Bounded Personal working-memory reset controls. These are canonical private
-- lifecycle inputs, never public Item Events, taste, history deletion or reward.
create table private.personal_working_resets (
  id uuid primary key,
  actor_user_id uuid not null references public.users(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  session_id uuid not null,
  reset_at timestamptz not null,
  created_at timestamptz not null,
  result jsonb not null check(jsonb_typeof(result)='object' and octet_length(result::text)<=2048),
  foreign key(session_id,actor_user_id,profile_id)
    references public.event_sessions(id,actor_user_id,profile_id) on delete cascade,
  check(pg_catalog.isfinite(reset_at) and reset_at>='epoch'::timestamptz and created_at=reset_at),
  check((result->>'version'='personal-working-reset-v1' and result->>'resetId'=id::text
    and result->>'actorUserId'=actor_user_id::text and result->>'profileId'=profile_id::text
    and result->>'sessionId'=session_id::text
    and (result->>'resetAt')::timestamptz=reset_at and (result->>'createdAt')::timestamptz=created_at) is true)
);
create index personal_working_resets_scope_time_idx
  on private.personal_working_resets(actor_user_id,profile_id,session_id,reset_at,created_at,id);
create index personal_working_resets_profile_idx on private.personal_working_resets(profile_id);
alter table private.personal_working_resets enable row level security;
revoke all on private.personal_working_resets from public,anon,authenticated,service_role;

create function private.guard_personal_working_reset_v1()
returns trigger language plpgsql volatile security invoker set search_path='' as $reset$
begin
  -- A parent cascade already owns its parent lock. Never acquire a late
  -- lifecycle/advisory lock here, or allow removal of a still-active raw control.
  if tg_op='DELETE' and (
    not exists(select 1 from public.users u where u.id=old.actor_user_id)
    or not exists(select 1 from public.profiles p where p.id=old.profile_id)
    or not exists(select 1 from public.event_sessions s where s.id=old.session_id
      and s.actor_user_id=old.actor_user_id and s.profile_id=old.profile_id)) then return old; end if;
  raise exception 'Personal working reset is immutable while its parents exist' using errcode='55000';
end;
$reset$;
create trigger personal_working_reset_immutable before update or delete on private.personal_working_resets
  for each row execute function private.guard_personal_working_reset_v1();

create function private.commit_personal_working_reset_v1(reset_id uuid,actor uuid,profile uuid,session uuid)
returns jsonb language plpgsql volatile security invoker set search_path='' set timezone='UTC' as $reset$
declare existing private.personal_working_resets%rowtype; current_session public.event_sessions%rowtype;
  reset_time timestamptz; receipt jsonb; control_count integer;
begin
  -- This gate is first, before receipt, Profile, User or session locks.
  perform pg_catalog.pg_advisory_xact_lock_shared(1946841873,232004);
  if actor is null or actor is distinct from auth.uid() then
    raise exception 'Personal working reset actor is unauthorized' using errcode='42501'; end if;
  if reset_id is null or profile is null or session is null then
    raise exception 'Personal working reset identity is required' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('personal-working-reset:'||reset_id,0));
  perform p.id from public.profiles p where p.id=profile for update;
  if not exists(select 1 from public.profiles p where p.id=profile
    and p.profile_type='PERSONAL' and p.owner_user_id=actor) then
    raise exception 'Personal working reset Profile is unauthorized' using errcode='42501'; end if;
  perform m.user_id from public.profile_members m where m.profile_id=profile and m.user_id=actor for key share;
  if not found then raise exception 'Personal working reset membership is unauthorized' using errcode='42501'; end if;
  select s.* into current_session from public.event_sessions s
    where s.id=session and s.actor_user_id=actor and s.profile_id=profile for key share;
  if current_session.id is null then
    raise exception 'Personal working reset requires an existing own session' using errcode='42501'; end if;
  -- Every retry reauthorizes. The frozen old receipt precedes quota/time checks.
  select r.* into existing from private.personal_working_resets r where r.id=reset_id;
  if found then
    if existing.actor_user_id<>actor or existing.profile_id<>profile or existing.session_id<>session then
      raise exception 'Personal working reset ID scope mismatch' using errcode='22023'; end if;
    return existing.result;
  end if;
  if pg_catalog.current_setting('transaction_isolation')<>'read committed' then
    raise exception 'New Personal working resets require READ COMMITTED' using errcode='25001'; end if;
  select count(*) into control_count from (select 1 from private.personal_working_resets r
    where r.actor_user_id=actor and r.profile_id=profile and r.session_id=session limit 129) bounded;
  if control_count>=128 then
    raise exception 'Personal working reset control quota exceeded' using errcode='54000'; end if;
  -- Store one full-precision server instant after every authorization/lock. This
  -- is a stored-time proxy, not a commit-availability certificate or TTL renewal.
  reset_time := pg_catalog.clock_timestamp();
  if not pg_catalog.isfinite(current_session.started_at) or not pg_catalog.isfinite(current_session.created_at)
    or current_session.started_at<'epoch'::timestamptz or current_session.created_at<'epoch'::timestamptz
    or current_session.started_at>reset_time or current_session.created_at>reset_time then
    raise exception 'Personal working reset session boundary is unavailable' using errcode='22023'; end if;
  receipt := jsonb_build_object('version','personal-working-reset-v1','resetId',reset_id,
    'actorUserId',actor,'profileId',profile,'sessionId',session,'resetAt',reset_time,'createdAt',reset_time,
    'affects','WORKING_STATE_ONLY','availabilityBasis','STORED_CREATED_TIME','commitAvailability','UNKNOWN',
    'historicalFeatureEligible',false,'learnable',false,'nativeActivated',false);
  insert into private.personal_working_resets(id,actor_user_id,profile_id,session_id,reset_at,created_at,result)
    values(reset_id,actor,profile,session,reset_time,reset_time,receipt);
  return receipt;
end;
$reset$;
revoke all on function private.guard_personal_working_reset_v1(),
  private.commit_personal_working_reset_v1(uuid,uuid,uuid,uuid) from public,anon,authenticated,service_role;


