ture->>'version' not in('native-working-capture-v1','native-working-capture-v2')\n    or not(case when capture->>'version'='native-working-capture-v2' then 'personal-working-off-v2'\n      else 'personal-working-off-v1' end=any(string_to_array(source.policy_version,'+')))","count":1},{"before":"or c.explanation#>>'{workingIntent,version}' is distinct from 'personal-working-features-v1'","after":"or c.explanation#>>'{workingIntent,version}' is distinct from case\n          when capture->>'version'='native-working-capture-v2' then 'personal-working-features-v2' else 'personal-working-features-v1' end","count":1},{"before":"  result := jsonb_build_object('version','personal-working-shadow-v1','sourcePredictionId',source.id,","after":"  result := jsonb_build_object('version',case when capture->>'version'='native-working-capture-v2'\n      then 'personal-working-shadow-v2' else 'personal-working-shadow-v1' end,'sourcePredictionId',source.id,","count":1},{"before":"  insert into private.personal_working_shadow_comparisons(source_prediction_id,control,result)","after":"  if capture->>'version'='native-working-capture-v2' then\n    result := result||jsonb_build_object('captureVersion',capture->'version',\n      'resetAt',capture->'resetAt','resetSourceRefs',capture->'resetSourceRefs');\n  end if;\n  insert into private.personal_working_shadow_comparisons(source_prediction_id,control,result)","count":1}]},{"signature":"private.rank_items_with_identity_v1(uuid,uuid,text,text,integer,jsonb)","sourceMd5":"ba0f54b3e35f66778dae442f298f3087","replacements":[{"before":"'+personal-working-off-v1'","after":"'+personal-working-off-v2'","count":1}]},{"signature":"private.rank_items_catalog_with_identity_v1(uuid[],boolean,uuid,uuid,text,text,integer,jsonb)","sourceMd5":"2504838fb61fd793dd0dc40a3c37f0bf","replacements":[{"before":"'+personal-working-off-v1'","after":"'+personal-working-off-v2'","count":1}]}]$reset_manifest$::jsonb) loop
    select p.oid,p.prosrc,to_jsonb(p)-'prosrc' metadata,pg_get_functiondef(p.oid) definition into strict previous
      from pg_catalog.pg_proc p where p.oid=(patch->>'signature')::regprocedure;
    if md5(previous.prosrc) is distinct from patch->>'sourceMd5' then
      raise exception 'Personal working reset source changed after preflight' using errcode='55000'; end if;
    next_source := previous.prosrc;
    for replacement in select value from jsonb_array_elements(patch->'replacements') loop
      before_text := replacement->>'before';
      if before_text='' or (length(next_source)-length(replace(next_source,before_text,'')))/length(before_text)
        <>(replacement->>'count')::integer then
        raise exception 'Personal working reset replacement drift' using errcode='55000'; end if;
      next_source := replace(next_source,before_text,replacement->>'after');
    end loop;
    if (length(previous.definition)-length(replace(previous.definition,previous.prosrc,'')))/length(previous.prosrc)<>1 then
      raise exception 'Personal working reset definition drift' using errcode='55000'; end if;
    execute replace(previous.definition,previous.prosrc,next_source);
    if not exists(select 1 from pg_catalog.pg_proc p where p.oid=previous.oid
      and to_jsonb(p)-'prosrc'=previous.metadata and p.prosrc=next_source) then
      raise exception 'Personal working reset function identity/metadata drift' using errcode='55000'; end if;
  end loop;
end;
$reset_patch$;
